heckpoints":[{"checkpoint_code":"U16-C01","title":"Línea base de tiempos","evidence_to_close":"p50/p95 y duraciones por etapa","status":"NOT_VERIFIED"},{"checkpoint_code":"U16-C02","title":"Transporte","evidence_to_close":"Canales, contratos y autenticación","status":"NOT_VERIFIED"},{"checkpoint_code":"U16-C03","title":"Payload","evidence_to_close":"Tamaño y límites de contenido","status":"NOT_VERIFIED"},{"checkpoint_code":"U16-C04","title":"Timeout/retry/idempotencia","evidence_to_close":"Controles de recuperación de fallos","status":"NOT_VERIFIED"},{"checkpoint_code":"U16-C05","title":"Profundidad de razonamiento","evidence_to_close":"Niveles dinámicos según necesidad","status":"NOT_VERIFIED"},{"checkpoint_code":"U16-C06","title":"Suficiencia de evidencia","evidence_to_close":"Grounding y políticas de calidad","status":"NOT_VERIFIED"},{"checkpoint_code":"U16-C07","title":"Consumo","evidence_to_close":"Tokens, CPU, memoria y concurrencia","status":"NOT_VERIFIED"},{"checkpoint_code":"U16-C08","title":"Observabilidad E2E","evidence_to_close":"Traza y correlación de eventos","status":"NOT_VERIFIED"},{"checkpoint_code":"U16-C09","title":"No regresión y rollback","evidence_to_close":"Prueba focalizada de cambios","status":"NOT_VERIFIED"},{"checkpoint_code":"U16-C10","title":"Benchmark y dictamen","evidence_to_close":"Cumplimiento medido de umbrales","status":"NOT_VERIFIED"}]}],"counts":{"units":17,"checkpoints":102,"verified_ai_sales_checkpoints":0},"dependencies":{"pe10":"Profile Updater PE10 exists in Supabase and has active backlog; read live states before reuse. No duplicate PE10 in AI Sales."},"content_sha256_without_digest":"f3038017950a0ade159cde1c607e529f1e80b8c4ec072f4f9508bc164795797d"}$ai_sales_json$::jsonb;
 exec_id text; event_id bigint; ws_id bigint; wi_id bigint;
 unit jsonb; cp jsonb; i int := 0; j int := 0; c_total int := 0;
 unit_code text; cp_code text;
 plan constant text := 'AI_SALES_3_0';
BEGIN
 SELECT execution_id INTO exec_id FROM public.lf_operation_execution
 WHERE operation_code='ACTUALIZACION_DB_LF' AND target_type='MIGRATION'
 AND target_code LIKE '%lf_ai_sales_3_0_plan_register_v0_2' AND status='IN_PROGRESS'
 ORDER BY created_at DESC LIMIT 1;
 IF exec_id IS NULL THEN RAISE EXCEPTION 'AI_SALES_PLAN_TRAIN_BINDING_REQUIRED'; END IF;
 IF p->>'plan_code'<>plan OR p->>'snapshot_version'<>'v0.2'
 OR p->>'status'<>'PROPOSED_NOT_REGISTERED'
 OR (p->'counts'->>'units')::int<>17 OR (p->'counts'->>'checkpoints')::int<>102
 OR (p->'counts'->>'verified_ai_sales_checkpoints')::int<>0
 OR jsonb_array_length(p->'units')<>17 OR jsonb_array_length(p->'gates')<>4
 THEN RAISE EXCEPTION 'AI_SALES_PLAN_SNAPSHOT_INVALID'; END IF;
 IF EXISTS (SELECT 1 FROM programacion.engineering_plan_units WHERE plan_code=plan)
 OR EXISTS (SELECT 1 FROM public.lf_eventos WHERE entidad_tipo='ENGINEERING_PLAN' AND entidad_codigo=plan)
 OR EXISTS (SELECT 1 FROM programacion.engineering_workstreams WHERE stream_code='WS-AI-SALES-3-0')
 OR EXISTS (SELECT 1 FROM programacion.engineering_work_items WHERE work_code LIKE 'AIS30-%')
 THEN RAISE EXCEPTION 'AI_SALES_PLAN_ALREADY_PRESENT_OR_PARTIAL'; END IF;
 INSERT INTO public.lf_eventos(evento_tipo,entidad_tipo,entidad_codigo,descripcion,severidad,payload,origen,created_by_execution_id)
 VALUES('PLAN_SNAPSHOT_DETALLADO','ENGINEERING_PLAN',plan,
 'Plan AI Sales 3.0 v0.2 borrador: 17 unidades, 102 checkpoints PENDING; sin ejecución.',
 'INFO',jsonb_build_object(
  'evidence_schema_version','operational-event/v2','producer','LF_MIGRATION_MERGE_TRAIN',
  'execution_id',exec_id,
  'purpose','Register AI Sales 3.0 draft plan with exact source and checkpoint readback, no activation.',
  'occurred_at',to_char(clock_timestamp() at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
  'plan_code',plan,'version','v0.2',
  'snapshot_digest',p->>'content_sha256_without_digest',
  'unit_count',17,'checkpoint_count',102,'status','DRAFT_NOT_EXECUTED',
  'source_ref','github://cristhianlujan/claude-persona-lf-patch/docs/ai_sales/AI_SALES_3_0_PLAN_V0_2_20261027.json',
  'snapshot',p,'acceptance_declared',false,'no_runtime_activation',true),
 'GOVERNED_MIGRATION_SOURCE_FIRST',exec_id)
 RETURNING id INTO event_id;
 INSERT INTO programacion.engineering_workstreams(
 stream_code,name,objective,owner_ref,status,source_ref,created_by_execution_id)
 VALUES('WS-AI-SALES-3-0','AI Sales 3.0 — Plan Maestro v0.2 (BORRADOR)',
 'Planificar 17 unidades de AI Sales con investigación, checkpoints y presupuesto de licencias/API inicialmente US$0.',
 'SUPER_ADMIN','PLANNED','event://' || event_id,exec_id) RETURNING id INTO ws_id;
 FOR unit IN SELECT value FROM jsonb_array_elements(p->'units') t(value)
 LOOP
  i:=i+1; unit_code:=unit->>'unit_code';
  IF unit_code IS DISTINCT FROM ('U'||lpad((i-1)::text,2,'0'))
   OR jsonb_typeof(unit->'checkpoints')<>'array'
  THEN RAISE EXCEPTION 'AI_SALES_UNIT_SEQUENCE_INVALID:%',i; END IF;
  INSERT INTO programacion.engineering_work_items(
   work_code,workstream_id,title,objective,expected_result,work_type,priority,status,
   assignee_type,assignee_ref,target_repo,target_domain,target_component,
   source_ref,acceptance_criteria,created_by_execution_id)
  VALUES('AIS30-'||unit_code,ws_id,unit_code||' — '||(unit->>'title'),
   'Investigar y desarrollar la unidad '||(unit->>'title')||' de AI Sales 3.0',
   'Checkpoint closure only upon observed functional evidence and authorized readback.',
   'AGENT_PLATFORM','P2','BACKLOG','MIXED','AI_SALES_PLAN_OWNER',
   'cristhianlujan/claude-persona-lf-patch','AI_SALES',unit_code,'event://' || event_id,
   jsonb_build_array('No duplicate or reopen PE10', 'Minimum focused tests; no unnecessary independent rounds',
   'No user-facing, model, CRM, production or runtime activation from plan registration'),
   exec_id) RETURNING id INTO wi_id;
  j:=0;
  FOR cp IN SELECT value FROM jsonb_array_elements(unit->'checkpoints') q(value)
  LOOP
   j:=j+1; cp_code:=cp->>'checkpoint_code';
   IF cp_code IS DISTINCT FROM (unit_code||'-C'||lpad(j::text,2,'0'))
     OR coalesce(length(cp->>'title'),0)<3
     OR coalesce(length(cp->>'evidence_to_close'),0)<6
     OR cp->>'status'<>'NOT_VERIFIED'
   THEN RAISE EXCEPTION 'AI_SALES_CHECKPOINT_CONTENT_INVALID:%',cp_code; END IF;
   INSERT INTO programacion.engineering_work_checkpoints(
      work_item_id,checkpoint_code,title,sequence_no,weight,required,status,created_by_execution_id)
   VALUES(wi_id,cp_code,cp->>'title',j,1,true,'PENDING',exec_id);
   c_total:=c_total+1;
  END LOOP;
  INSERT INTO programacion.engineering_plan_units(
   plan_code,unit_code,unit_class,lot_code,lot_from,lot_to,title,exit_criterion,
   plan_event_id,work_item_id,created_by_execution_id,unit_metadata)
  VALUES(plan,unit_code,'EXECUTION',coalesce(unit->>'phase','TRANSVERSAL'),i,i,
   unit_code||' — '||(unit->>'title'),
   'Cerrar solo con evidencia pertinente y controles mínimos, sin auditorías repetidas.',
   event_id,wi_id,exec_id,
   jsonb_build_object(
    'schema','AI_SALES_DRAFT_UNIT_V0_2','scope','PLAN_ONLY_NO_EXECUTION',
    'unit_index',i,'phase',unit->>'phase','checkpoint_count',j,
    'source_digest',p->>'content_sha256_without_digest',
    'checkpoint_inputs',(SELECT jsonb_object_agg(q.value->>'checkpoint_code',
      jsonb_build_object('evidence_to_close',q.value->>'evidence_to_close',
       'title',q.value->>'title','status','PENDING'))
     FROM jsonb_array_elements(unit->'checkpoints') q(value)),
    'gates',p->'gates','execution_order_note',p->'execution_order_note',
    'dependency_binding','PROPOSED_NOT_EXECUTABLE',
    'no_production_change',true,'independent_review_only_if_material_risk',true));
 END LOOP;
 IF i<>17 OR c_total<>102
 OR (SELECT count(*) FROM programacion.engineering_plan_units WHERE plan_code=plan)<>17
 OR (SELECT count(*) FROM programacion.engineering_work_checkpoints c
     JOIN programacion.engineering_plan_units u ON u.work_item_id=c.work_item_id
     WHERE u.plan_code=plan AND c.status='PENDING')<>102
 THEN RAISE EXCEPTION 'AI_SALES_PLAN_POSTSTATE_MISMATCH'; END IF;
END;
$register_ai_sales$;
COMMIT;
